import React from "react";

function Video( {path,className} ) {
  return (
    <div className=" md:w-1/2  {}">
      <video
        src={path}
        loop
        autoPlay
        muted
        className="md:h-screen w-full "
      ></video>
    </div>
  );
}

export default Video;
